html body.home .wp-site-blocks .mlx-journeys, html body.home .wp-site-blocks .mlx-journeys > section:not(.mlx-lang2), html body.home .wp-site-blocks .mlx-journeys > .mlx-lang2 { margin-top: 0 !important; margin-bottom: 0 !important; }
@media (min-width: 1100px) {
  html body.home { --mlx-u: calc((100svh - var(--wp-admin--admin-bar--height, 0px)) / 100); }
  html body.home .wp-site-blocks .mlx-journeys { display: grid !important; grid-template-columns: repeat(2, minmax(0, 632px)); justify-content: center; align-content: center; column-gap: 24px;
    row-gap: clamp(12px, calc(3 * var(--mlx-u) - 5px), 34px); padding: clamp(10px, calc(2 * var(--mlx-u)), 28px) 40px !important; box-sizing: border-box; background: #fff;
    min-height: calc(100svh - 72px - var(--wp-admin--admin-bar--height, 0px)); }
  html body.home .wp-site-blocks .mlx-journeys > .mlx-lang2 { grid-column: 1 / -1; padding: 0 !important; position: relative; z-index: 2; background: transparent; }
  html body.home .mlx-journeys .mlx-lang2-card { max-width: none; padding-top: clamp(14px, calc(2.6 * var(--mlx-u)), 30px); padding-bottom: clamp(14px, calc(2.6 * var(--mlx-u)), 30px); }
  html body.home .mlx-journeys .mlx-lang2-k { margin-bottom: 6px; }
  html body.home .mlx-journeys .mlx-lang2-h { font-size: clamp(26px, calc(1.4 * var(--mlx-u) + 18px), 34px); margin-bottom: 6px; }
  html body.home .mlx-journeys .mlx-lang2-p { font-size: 15px; }
  html body.home .wp-site-blocks .mlx-journeys > section:not(.mlx-lang2) { padding: clamp(12px, calc(5.2 * var(--mlx-u) - 19px), 34px) 20px !important; border-radius: 28px;
    border: 1.5px solid rgba(212,162,76,.55); box-shadow: 0 18px 36px -24px rgba(22,20,31,.45); background: #fbf8f2 !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-section-intro { margin: 0 !important; padding: 0 !important; gap: 0 !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-section-intro > * { margin-top: 0 !important; margin-bottom: 0 !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-section-intro h2 { font-size: clamp(24px, calc(2.26 * var(--mlx-u) + 10.5px), 34px) !important; line-height: 1.1 !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-section-intro h2::after { margin-top: clamp(8px, calc(2 * var(--mlx-u) - 4px), 18px) !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-section-intro p { font-size: clamp(14px, calc(0.48 * var(--mlx-u) + 10.9px), 16px) !important; margin-top: 4px !important; line-height: 1.4 !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-section-intro p br { display: none; }
  html body.home .wp-site-blocks .mlx-journeys .ext-grid { display: flex !important; flex-direction: column; gap: clamp(6px, calc(2.25 * var(--mlx-u) - 7.5px), 16px) !important; margin-top: clamp(8px, calc(3.2 * var(--mlx-u) - 10px), 24px) !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-grid > .ext-card.ext-card { min-height: 0 !important; padding: clamp(8px, calc(3.6 * var(--mlx-u) - 13px), 26px) 18px !important; border-radius: 16px !important; align-items: stretch !important; justify-content: center !important; }   /* centred when a card is stretched to its partner's height (assets/home_journeys_align.js) */
  html body.home .wp-site-blocks .mlx-journeys .ext-grid > .ext-card.ext-card:not(.x):has(figure) * { text-align: left !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-card-body.ext-card-body { padding: 0 0 0 min(52px, 4.2vw) !important; display: block !important; position: relative; }
  html body.home .wp-site-blocks .mlx-journeys .ext-card-body > figure.wp-block-image.wp-block-image:not(.x):not(.y) { position: absolute !important; left: 0; top: 50%; transform: translateY(-50%); margin: 0 !important; width: min(34px, 2.75vw) !important; height: auto !important; min-height: 0 !important; padding: 0 !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-card-body > figure.wp-block-image.wp-block-image:not(.x):not(.y)::before { font-size: min(clamp(36px, calc(2.8 * var(--mlx-u) + 19px), 50px), 3vw) !important; line-height: 1 !important; text-align: center !important; display: block; margin: 0 !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-card-body > h3 { font-size: min(clamp(20px, calc(1.3 * var(--mlx-u) + 12px), 28px), 1.64vw) !important; margin: 0 !important; line-height: 1.2 !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-card-body > p { font-size: min(clamp(15px, calc(0.6 * var(--mlx-u) + 11.4px), 19px), 1.23vw) !important; line-height: 1.4 !important; margin: 2px 0 0 !important; }
}
/* where the medical intro needs two lines (narrow 1100-1233 px screens, tall screens from about 1000 px), both intros get a two-line slot so the cards of both columns start at the same height */
