/* >>> LANG-SWITCHER START: header language dropdown (TranslatePress) on a solid dark panel – it was transparent and the language names floated over the page (unreadable on white). 2026-10-17 (Anna) */
header .trp-shortcode-overlay.is-open { background: #0b0620 !important; border: 1px solid rgba(212, 162, 76, 0.55) !important; border-radius: 12px !important; box-shadow: 0 16px 34px -14px rgba(0, 0, 0, 0.6) !important; }
