@media (prefers-reduced-motion: reduce) {
  .medlux-hub-box, .medlux-rows .medlux-row, .medlux-steps .medlux-card, .medlux-treatment-grid .medlux-card, .medlux-dept-grid .medlux-card, .medlux-hub-box .medlux-hub-img img, .medlux-row-img img { transition: none; }
}
